				set identity_insert departments on;
                if not exists(select deptid from departments where code = '%(code)s')
                    insert into departments (deptid,code,deptname,supdeptid,type,status) values(%(deptid)s,'%(code)s', '%(deptname)s', %(supdeptid)s, 'dept',0)
                set identity_insert departments off;
